// ABOUTME: Data model for native ProofMode library proof metadata
// ABOUTME: Stores cryptographic proof data from Guardian Project libProofMode

/// Native ProofMode proof data from libProofMode library
///
/// Generated by native Android/iOS ProofMode libraries after video recording.
/// Simpler than ProofManifest - doesn't track recording sessions/segments,
/// just provides cryptographic proof for the final video file.
class NativeProofData {
  const NativeProofData({
    required this.videoHash,
    this.sensorDataCsv,
    this.pgpSignature,
    this.publicKey,
    this.deviceAttestation,
    this.timestamp,
    this.c2paManifestId,
    this.creatorBindingAssertionLabel,
    this.cawgIdentityAssertionLabel,
    this.creatorBindingPayloadJson,
    this.verifiedIdentityBundleJson,
    this.unattestedSources = false,
  });

  /// Create from JSON
  factory NativeProofData.fromJson(
    Map<String, dynamic> json,
  ) => NativeProofData(
    videoHash: json['videoHash'] as String,
    sensorDataCsv: json['sensorDataCsv'] as String?,
    pgpSignature: json['pgpSignature'] as String?,
    publicKey: json['publicKey'] as String?,
    deviceAttestation: json['deviceAttestation'] as String?,
    timestamp: json['timestamp'] as String?,
    c2paManifestId: json['c2paManifestId'] as String?,
    creatorBindingAssertionLabel:
        json['creatorBindingAssertionLabel'] as String?,
    cawgIdentityAssertionLabel: json['cawgIdentityAssertionLabel'] as String?,
    creatorBindingPayloadJson: json['creatorBindingPayloadJson'] as String?,
    verifiedIdentityBundleJson: json['verifiedIdentityBundleJson'] as String?,
    unattestedSources: json['unattestedSources'] as bool? ?? false,
  );

  /// Create from raw proof metadata map (from NativeProofModeService)
  factory NativeProofData.fromMetadata(
    Map<String, String> metadata, {
    bool unattestedSources = false,
  }) => NativeProofData(
    videoHash: metadata[metadataHashKey]!,
    sensorDataCsv: metadata[metadataSensorDataCsvKey],
    pgpSignature: metadata[metadataPgpSignatureKey],
    publicKey: metadata[metadataPublicKeyKey],
    c2paManifestId: metadata[metadataC2paManifestIdKey],
    deviceAttestation: metadata[metadataDeviceAttestationKey],
    unattestedSources: unattestedSources,
  );

  static const metadataHashKey = 'hash';
  static const metadataSensorDataCsvKey = 'csv';
  static const metadataPgpSignatureKey = 'signature';
  static const metadataPublicKeyKey = 'publicKey';
  static const metadataDeviceAttestationKey = 'deviceAttestation';
  static const metadataC2paManifestIdKey = 'c2pa_manifest_id';

  /// SHA256 hash of the video file (used as proof identifier)
  final String videoHash;

  /// CSV sensor data (location, network, device info, etc.)
  final String? sensorDataCsv;

  /// OpenPGP signature of the video file
  final String? pgpSignature;

  /// PGP public key used for signing
  final String? publicKey;

  /// Device attestation token (Google SafetyNet on Android)
  final String? deviceAttestation;

  /// Timestamp of proof generation
  final String? timestamp;

  /// C2PA manifest data
  final String? c2paManifestId;

  /// Assertion label for the user-signed Nostr creator binding
  final String? creatorBindingAssertionLabel;

  /// Assertion label for the optional CAWG identity overlay
  final String? cawgIdentityAssertionLabel;

  /// Canonical JSON payload signed by the creator's Nostr key
  final String? creatorBindingPayloadJson;

  /// Verifier response JSON for portable identity claims
  final String? verifiedIdentityBundleJson;

  /// Whether the video was deliberately left without a C2PA manifest because
  /// media it was edited from carries no camera proof.
  ///
  /// Signing such an edit would vouch for footage nobody can show was
  /// recorded, so its missing [c2paManifestId] is expected, not a failure to
  /// retry.
  final bool unattestedSources;

  /// Convert to JSON for storage
  Map<String, dynamic> toJson() => {
    'videoHash': videoHash,
    if (sensorDataCsv != null) 'sensorDataCsv': sensorDataCsv,
    if (pgpSignature != null) 'pgpSignature': pgpSignature,
    if (publicKey != null) 'publicKey': publicKey,
    if (deviceAttestation != null) 'deviceAttestation': deviceAttestation,
    if (timestamp != null) 'timestamp': timestamp,
    if (c2paManifestId != null) 'c2paManifestId': c2paManifestId,
    if (creatorBindingAssertionLabel != null)
      'creatorBindingAssertionLabel': creatorBindingAssertionLabel,
    if (cawgIdentityAssertionLabel != null)
      'cawgIdentityAssertionLabel': cawgIdentityAssertionLabel,
    if (creatorBindingPayloadJson != null)
      'creatorBindingPayloadJson': creatorBindingPayloadJson,
    if (verifiedIdentityBundleJson != null)
      'verifiedIdentityBundleJson': verifiedIdentityBundleJson,
    if (unattestedSources) 'unattestedSources': true,
  };

  /// Copy carrying exactly [attestation] as its device attestation.
  ///
  /// Takes the value verbatim, `null` included, so a caller that owns the field
  /// can clear a stale token as well as set a fresh one — which a nullable
  /// `copyWith` parameter cannot express.
  NativeProofData withDeviceAttestation(String? attestation) => NativeProofData(
    videoHash: videoHash,
    sensorDataCsv: sensorDataCsv,
    pgpSignature: pgpSignature,
    publicKey: publicKey,
    deviceAttestation: attestation,
    timestamp: timestamp,
    c2paManifestId: c2paManifestId,
    creatorBindingAssertionLabel: creatorBindingAssertionLabel,
    cawgIdentityAssertionLabel: cawgIdentityAssertionLabel,
    creatorBindingPayloadJson: creatorBindingPayloadJson,
    verifiedIdentityBundleJson: verifiedIdentityBundleJson,
    unattestedSources: unattestedSources,
  );

  /// Copy reporting [unattested] as [unattestedSources].
  NativeProofData withUnattestedSources({required bool unattested}) =>
      NativeProofData(
        videoHash: videoHash,
        sensorDataCsv: sensorDataCsv,
        pgpSignature: pgpSignature,
        publicKey: publicKey,
        deviceAttestation: deviceAttestation,
        timestamp: timestamp,
        c2paManifestId: c2paManifestId,
        creatorBindingAssertionLabel: creatorBindingAssertionLabel,
        cawgIdentityAssertionLabel: cawgIdentityAssertionLabel,
        creatorBindingPayloadJson: creatorBindingPayloadJson,
        verifiedIdentityBundleJson: verifiedIdentityBundleJson,
        unattestedSources: unattested,
      );

  /// Check if creator identity metadata was attached to the proof payload
  bool get hasCreatorIdentityMetadata =>
      creatorBindingAssertionLabel != null ||
      cawgIdentityAssertionLabel != null ||
      creatorBindingPayloadJson != null ||
      verifiedIdentityBundleJson != null;

  /// Check if proof data is complete
  bool get isComplete =>
      pgpSignature != null && publicKey != null && sensorDataCsv != null;

  /// Check if this is a mobile proof with device attestation
  bool get hasMobileAttestation =>
      deviceAttestation != null || c2paManifestId != null;

  /// Get verification level for Nostr tags
  String get verificationLevel {
    if (hasMobileAttestation && pgpSignature != null) {
      return 'verified_mobile';
    }
    if (pgpSignature != null) {
      return 'verified_web';
    }
    if (sensorDataCsv != null) {
      return 'basic_proof';
    }
    return 'unverified';
  }

  /// Get PGP fingerprint from public key (simplified)
  String? get pgpFingerprint {
    if (publicKey == null) return null;
    // TODO(any): Extract actual fingerprint from PGP public key.
    // For now, return first 40 chars of key as placeholder
    return publicKey!.length > 40 ? publicKey!.substring(0, 40) : publicKey;
  }

  @override
  String toString() =>
      'NativeProofData(hash: $videoHash, '
      'hasSignature: ${pgpSignature != null}, '
      'hasAttestation: ${deviceAttestation != null})';
}
